impl Solution {
    pub fn min_cutting_cost(n: i32, m: i32, k: i32) -> i64 {
        let n = n as i64;
        let m = m as i64;
        let k = k as i64;

        // Helper function to calculate the cost of cutting a log of length x into parts <= k
        fn min_cost(x: i64, k: i64) -> i64 {
            if x <= k {
                return 0;
            }
            // The optimal way is to cut into two parts as balanced as possible
            let half = x / 2;
            let cost = half * (x - half);
            cost + min_cost(half, k) + min_cost(x - half, k)
        }

        // We have two logs, so we need to consider all possible ways to cut them
        // The total cost is the sum of the costs for each log
        min_cost(n, k) + min_cost(m, k)
    }
}

